<script>
document.addEventListener('DOMContentLoaded',()=>{
 const provider=document.getElementById('sms-provider'),endpoint=document.getElementById('sms-endpoint');provider.addEventListener('change',()=>{if(!endpoint.value || ['https://api.ng.termii.com','https://www.bulksmsnigeria.com/api/v2'].includes(endpoint.value))endpoint.value=provider.value==='termii'?'https://api.ng.termii.com':'https://www.bulksmsnigeria.com/api/v2'});
 document.querySelectorAll('.sms-audit-type').forEach(type=>{const form=type.closest('form'),search=form.querySelector('.sms-area-search'),area=form.querySelector('.sms-area-select'),status=form.querySelector('.sms-area-status');let timer,controller;const toggle=()=>{const enabled=!['own','national'].includes(type.value);search.disabled=area.disabled=!enabled;return enabled};const load=async()=>{if(!toggle())return;controller?.abort();controller=new AbortController();status.textContent='Loading areas…';try{const r=await fetch(@json(route($prefix.'boundaries'))+'?'+new URLSearchParams({type:type.value,search:search.value}),{headers:{Accept:'application/json'},signal:controller.signal});if(!r.ok)throw Error();const data=await r.json();area.replaceChildren(new Option('Choose an area',''));for(const row of data.data)area.add(new Option(row.name,row.id));status.textContent=data.data.length===50?'Showing 50 areas. Refine your search.':(data.data.length?'Select an area.':'No matching areas.');}catch(e){if(e.name!=='AbortError')status.textContent='Could not load areas. Try again.'}};type.addEventListener('change',()=>{area.replaceChildren(new Option('Choose an area',''));search.value='';load()});search.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(load,300)});toggle();});
});
</script>
